// This fixture was generated by npm cmd-shim 8.0.0 from a plain Node shebang.
// Keep it independent of the production template matcher.
func writeNpmDevFixture(t *testing.T, host string, local bool) (shim, entry string) {
	t.Helper()
	base := filepath.Join(t.TempDir(), "tools with spaces 你好")
	name, target := "@qwen-code/qwen-code", "cli-entry.js"
	if host == "codex" {
		name, target = "@openai/codex", "bin/codex.js"
	}
	dir := base
	if local {
		dir = filepath.Join(base, "node_modules", ".bin")
	}
	entry = filepath.Join(base, "node_modules", filepath.FromSlash(name), filepath.FromSlash(target))
	mustWriteDevFile(t, entry, []byte("#!/usr/bin/env node\n"))
	manifest, _ := json.Marshal(map[string]any{"name": name, "bin": map[string]string{host: target}})
	mustWriteDevFile(t, filepath.Join(base, "node_modules", filepath.FromSlash(name), "package.json"), manifest)
	template, err := os.ReadFile("testdata/npm-node.cmd")
	if err != nil {
		t.Fatal(err)
	}
	rel, err := filepath.Rel(dir, entry)
	if err != nil {
		t.Fatal(err)
	}
	wrapper := strings.ReplaceAll(string(template), `node_modules\@qwen-code\qwen-code\cli-entry.js`, strings.ReplaceAll(rel, "/", `\`))
	shim = filepath.Join(dir, host+".cmd")
	mustWriteDevFile(t, shim, []byte(wrapper))
	mustWriteDevFile(t, filepath.Join(dir, "node.exe"), []byte("owned Node fixture"))
	return shim, entry
}
func mustWriteDevFile(t *testing.T, path string, data []byte) {
	t.Helper()
	if err := os.MkdirAll(filepath.Dir(path), 0755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, data, 0700); err != nil {
		t.Fatal(err)
	}
}

func TestNpmDevCommand(t *testing.T) {
	for _, host := range []string{"codex", "qwen"} {
		for _, local := range []bool{false, true} {
			t.Run(host+map[bool]string{false: "-global", true: "-local"}[local], func(t *testing.T) {
				shim, entry := writeNpmDevFixture(t, host, local)
				node, got, err := npmDevCommand(host, shim)
				if err != nil || got != entry || node != filepath.Join(filepath.Dir(shim), "node.exe") {
					t.Fatalf("resolve: %q %q %v", node, got, err)
				}
				wrapper := readFileString(t, shim)
				mustWriteDevFile(t, shim, []byte(strings.ReplaceAll(wrapper, "\r\n", "\n")))
				if _, _, err := npmDevCommand(host, shim); err != nil {
					t.Fatalf("LF: %v", err)
				}
			})
		}
	}
}

func TestNpmDevRejectsUnknownLaunchers(t *testing.T) {
	for _, mode := range []string{"changed-bin", "custom-prelude", "custom-flags", "wrong-target", "bad-json", "wrong-name", "missing-bin", "escape-bin", "missing-entry", "entry-directory", "sibling-directory", "missing-node", "unknown-name"} {
		t.Run(mode, func(t *testing.T) {
			shim, entry := writeNpmDevFixture(t, "qwen", false)
			manifest := filepath.Join(filepath.Dir(entry), "package.json")
			switch mode {
			case "changed-bin":
				mustWriteDevFile(t, manifest, []byte(`{"name":"@qwen-code/qwen-code","bin":{"qwen":"%TARGET%.js"}}`))
				mustWriteDevFile(t, filepath.Join(filepath.Dir(entry), "%TARGET%.js"), []byte("#!/usr/bin/env node\n"))
				mustWriteDevFile(t, shim, []byte(strings.ReplaceAll(readFileString(t, shim), "cli-entry.js", "%TARGET%.js")))
			case "custom-prelude":
				mustWriteDevFile(t, shim, []byte("SET CUSTOM=1\r\n"+readFileString(t, shim)))
			case "custom-flags":
				mustWriteDevFile(t, shim, []byte(strings.ReplaceAll(readFileString(t, shim), `"%_prog%"  `, `"%_prog%" --trace-warnings `)))
			case "wrong-target":
				mustWriteDevFile(t, shim, []byte(strings.ReplaceAll(readFileString(t, shim), "cli-entry.js", "other.js")))
			case "bad-json":
				mustWriteDevFile(t, manifest, []byte("{"))
			case "wrong-name":
				mustWriteDevFile(t, manifest, []byte(`{"name":"other","bin":{"qwen":"cli-entry.js"}}`))
			case "missing-bin":
				mustWriteDevFile(t, manifest, []byte(`{"name":"@qwen-code/qwen-code"}`))
			case "escape-bin":
				mustWriteDevFile(t, manifest, []byte(`{"name":"@qwen-code/qwen-code","bin":{"qwen":"../outside.js"}}`))
			case "missing-entry":
				if err := os.Remove(entry); err != nil {
					t.Fatal(err)
				}
			case "entry-directory":
				if err := os.Remove(entry); err != nil {
					t.Fatal(err)
				}
				if err := os.Mkdir(entry, 0700); err != nil {
					t.Fatal(err)
				}
			case "sibling-directory":
				node := filepath.Join(filepath.Dir(shim), "node.exe")
				if err := os.Remove(node); err != nil {
					t.Fatal(err)
				}
				if err := os.Mkdir(node, 0700); err != nil {
					t.Fatal(err)
				}
			case "missing-node":
				if err := os.Remove(filepath.Join(filepath.Dir(shim), "node.exe")); err != nil {
					t.Fatal(err)
				}
				t.Setenv("PATH", t.TempDir())
			case "unknown-name":
				other := filepath.Join(filepath.Dir(shim), "custom.cmd")
				mustWriteDevFile(t, other, []byte(readFileString(t, shim)))
				shim = other
			}
			if _, _, err := npmDevCommand("qwen", shim); err == nil {
				t.Fatal("accepted unsupported launcher")
			}
		})
	}
}

func TestWindowsDevNpmArgv(t *testing.T) {
	if runtime.GOOS != "windows" {
		t.Skip("native Windows executable resolution")
	}
	helper := buildDevAgent(t)
	binary, err := os.ReadFile(helper)
	if err != nil {
		t.Fatal(err)
	}
	for _, host := range []string{"codex", "qwen"} {
		for _, local := range []bool{false, true} {
			for _, sibling := range []bool{false, true} {
				name := host + map[bool]string{true: "-local", false: "-global"}[local] + map[bool]string{true: "-sibling", false: "-path"}[sibling]
				t.Run(name, func(t *testing.T) {
					shim, entry := writeNpmDevFixture(t, host, local)
					nodePath := filepath.Join(filepath.Dir(shim), "node.exe")
					pathDir := t.TempDir()
					pathNode := filepath.Join(pathDir, "node.exe")
					if sibling {
						mustWriteDevFile(t, nodePath, binary)
						// A broken PATH node must not replace the shim's sibling interpreter.
						mustWriteDevFile(t, pathNode, []byte("not an executable"))
					} else {
						if err := os.Remove(nodePath); err != nil {
							t.Fatal(err)
						}
						mustWriteDevFile(t, pathNode, binary)
					}
					t.Setenv("PATH", pathDir)
					t.Setenv("PITOT_TEST_NODE", "1")
					t.Setenv("PITOT_TEST_MODE", "record")
					seen := t.TempDir()
					t.Setenv("PITOT_TEST_SEEN", seen)
					args := []string{"", "a b", `say "hi"`, `C:\path with space\`, "你好", "&|<>^%!()"}
					executable, argv, err := devCommand(host, shim, args)
					if err != nil {
						t.Fatal(err)
					}
					expectedNode := pathNode
					if sibling {
						expectedNode = nodePath
					}
					if executable != expectedNode || argv[0] != entry {
						t.Fatalf("wrong invocation: %q %#v", executable, argv)
					}
					if out, err := exec.CommandContext(context.Background(), executable, argv...).CombinedOutput(); err != nil {
						t.Fatalf("launch: %v %s", err, out)
					}
					var got []string
					if err := json.Unmarshal([]byte(readFileString(t, filepath.Join(seen, "args.json"))), &got); err != nil {
						t.Fatal(err)
					}
					if !reflect.DeepEqual(got, args) {
						t.Fatalf("argv: %#v, want %#v", got, args)
					}
					direct, directArgs, err := devCommand(host, expectedNode, args)
					if err != nil || direct != expectedNode || !reflect.DeepEqual(directArgs, args) {
						t.Fatalf("direct executable changed: %q %#v %v", direct, directArgs, err)
					}
				})
			}
		}
	}
}
